import {
  CopyObjectCommand,
  CreateBucketCommand,
  DeleteObjectCommand,
  GetObjectCommand,
  HeadBucketCommand,
  PutObjectCommand,
  S3Client,
} from "@aws-sdk/client-s3";

/**
 * Object storage behind the S3 API. Server-side only (actions, route handlers,
 * the seed); nothing here is imported by client components. docker compose runs SeaweedFS; pointing
 * S3_ENDPOINT at AWS S3, Cloudflare R2 or any other S3-compatible service is
 * a configuration change. Keys are generated by the app (see images.ts), never
 * taken from a request.
 */
export type StorageConfig = {
  endpoint: string;
  region: string;
  bucket: string;
  accessKeyId: string;
  secretAccessKey: string;
  forcePathStyle: boolean;
};

function storageConfig(): StorageConfig {
  const env = process.env;
  const endpoint = env.S3_ENDPOINT;
  if (!endpoint) throw new Error("S3_ENDPOINT is not set");
  return {
    endpoint,
    region: env.S3_REGION || "us-east-1",
    bucket: env.S3_BUCKET || "julinks",
    accessKeyId: env.S3_ACCESS_KEY_ID || "",
    secretAccessKey: env.S3_SECRET_ACCESS_KEY || "",
    // SeaweedFS, MinIO and most self-hosted services address buckets by path, not by subdomain.
    forcePathStyle: env.S3_FORCE_PATH_STYLE !== "false",
  };
}

const globalForStorage = globalThis as unknown as { s3?: S3Client; s3Bucket?: Promise<void> };

function client(): S3Client {
  if (!globalForStorage.s3) {
    const cfg = storageConfig();
    globalForStorage.s3 = new S3Client({
      endpoint: cfg.endpoint,
      region: cfg.region,
      forcePathStyle: cfg.forcePathStyle,
      credentials: { accessKeyId: cfg.accessKeyId, secretAccessKey: cfg.secretAccessKey },
      // Plain bodies instead of aws-chunked streaming with trailing checksums, which not every S3 clone accepts.
      requestChecksumCalculation: "WHEN_REQUIRED",
      responseChecksumValidation: "WHEN_REQUIRED",
    });
  }
  return globalForStorage.s3;
}

/** Creates the bucket on first use so a fresh storage volume needs no manual setup. Once per process. */
async function ensureBucket(): Promise<void> {
  if (!globalForStorage.s3Bucket) {
    const { bucket } = storageConfig();
    globalForStorage.s3Bucket = client()
      .send(new HeadBucketCommand({ Bucket: bucket }))
      .then(
        () => undefined,
        async () => {
          await client().send(new CreateBucketCommand({ Bucket: bucket }));
        },
      )
      .catch((error) => {
        globalForStorage.s3Bucket = undefined;
        throw error;
      });
  }
  return globalForStorage.s3Bucket;
}

export async function putObject(key: string, body: Uint8Array, contentType: string): Promise<void> {
  await ensureBucket();
  const { bucket } = storageConfig();
  await client().send(
    new PutObjectCommand({
      Bucket: bucket,
      Key: key,
      Body: body,
      ContentType: contentType,
      CacheControl: "public, max-age=31536000, immutable",
    }),
  );
}

export type StoredObject = { body: ReadableStream<Uint8Array>; contentType: string; contentLength?: number };

/** The object as a web stream, or null when the key does not exist. */
export async function getObject(key: string): Promise<StoredObject | null> {
  await ensureBucket();
  const { bucket } = storageConfig();
  try {
    const out = await client().send(new GetObjectCommand({ Bucket: bucket, Key: key }));
    if (!out.Body) return null;
    return {
      body: out.Body.transformToWebStream(),
      contentType: out.ContentType ?? "application/octet-stream",
      contentLength: out.ContentLength,
    };
  } catch (error) {
    if (isNotFound(error)) return null;
    throw error;
  }
}

/** Best effort: a missing key is not an error, so callers can delete old versions freely. */
export async function deleteObject(key: string): Promise<void> {
  await ensureBucket();
  const { bucket } = storageConfig();
  try {
    await client().send(new DeleteObjectCommand({ Bucket: bucket, Key: key }));
  } catch (error) {
    if (!isNotFound(error)) throw error;
  }
}

/** Server-side copy, used when a theme with a background image is copied by another user. */
export async function copyObject(fromKey: string, toKey: string): Promise<void> {
  await ensureBucket();
  const { bucket } = storageConfig();
  await client().send(new CopyObjectCommand({ Bucket: bucket, CopySource: `/${bucket}/${fromKey}`, Key: toKey }));
}

function isNotFound(error: unknown): boolean {
  const e = error as { name?: string; $metadata?: { httpStatusCode?: number } };
  return e?.name === "NoSuchKey" || e?.name === "NotFound" || e?.$metadata?.httpStatusCode === 404;
}
